import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Codex Remote","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/codex-remote.md","filePath":"zh/products/ai-coding/codex/codex-remote.md","lastUpdated":1787110548000}'),d={name:"zh/products/ai-coding/codex/codex-remote.md"};function n(s,t,l,c,h,p){return o(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="codex-remote" tabindex="-1">Codex Remote <a class="header-anchor" href="#codex-remote" aria-label="Permalink to &quot;Codex Remote&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>——把 ChatGPT 手机应用和一台 Mac / Windows 主机配对，然后在手机上启动、带方向、审批、审 Codex 任务。<strong>干活的是那台已连接电脑</strong>。Remote 不是 Cloud。</p><p>官方落地页：<a href="https://learn.chatgpt.com/codex/remote" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/remote</a>。安装与安全：<a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要</th><th>要求</th></tr></thead><tbody><tr><td>主机</td><td>最新 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a>，macOS 或 Windows，醒着且在线</td></tr><tr><td>手机</td><td>最新 ChatGPT iOS / Android，能看到 <strong>Remote</strong></td></tr><tr><td>账号</td><td>两端同一 ChatGPT 账号<strong>和</strong> workspace</td></tr><tr><td>权限</td><td>该账号有 Codex；企业管理员可能要打开 Remote Control</td></tr></tbody></table><p>可用性取决于放量和 workspace 设置。不能从 CLI 或 IDE 发起配对。</p><p><strong>学习目标</strong>：一对一配对；启动或续上任务；审批一条命令；看 diff；明白主机必须醒着。</p><p><strong>非目标</strong>：托管环境（<a href="./codex-cloud.html">Cloud</a>）；<code>codex app-server</code> JSON-RPC（<a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a>）；桌面 Work 与 Codex 对照（<a href="./chatgpt-work.html">Work</a>）。</p><h2 id="remote-是什么-不是什么" tabindex="-1">Remote 是什么，不是什么 <a class="header-anchor" href="#remote-是什么-不是什么" aria-label="Permalink to &quot;Remote 是什么，不是什么&quot;">​</a></h2><p>Remote 是<strong>控制面</strong>。手机发提示词、审批和追问。主机提供仓库、shell、插件、Computer Use、浏览器、凭证和沙箱。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>手机（ChatGPT mobile · Remote）</span></span>
<span class="line"><span>        │  提示词 / 审批 / 审阅</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>主机（ChatGPT desktop · Mac 或 Windows）</span></span>
<span class="line"><span>        │  文件、shell、插件、Computer Use</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>可选：另一台机器上的 SSH 项目</span></span></code></pre></div><p>它<strong>不是</strong>：</p><ul><li><a href="./codex-cloud.html">Codex Cloud</a>。Cloud 跑在 OpenAI 托管机上，不需要你的笔记本。</li><li>公网监听。配对走中继；不要把 <code>codex app-server</code> 暴露到互联网。</li><li>在你还要用的同一 Windows 会话里做 Computer Use。Windows 上 Computer Use 会占前台。</li></ul><h2 id="第-1-步-—-在主机上开始设置" tabindex="-1">第 1 步 — 在主机上开始设置 <a class="header-anchor" href="#第-1-步-—-在主机上开始设置" aria-label="Permalink to &quot;第 1 步 — 在主机上开始设置&quot;">​</a></h2><p>在 Mac 或 Windows 上：</p><ol><li>打开 ChatGPT 桌面应用。</li><li>进入 <strong>Settings → Connections → Control this Mac or PC</strong>。</li><li>选 <strong>Set up</strong> 或 <strong>Add</strong>。</li><li>批准远程访问，完成验证。</li></ol><p>只配对你拥有且信任的设备。</p><h2 id="第-2-步-—-扫二维码" tabindex="-1">第 2 步 — 扫二维码 <a class="header-anchor" href="#第-2-步-—-扫二维码" aria-label="Permalink to &quot;第 2 步 — 扫二维码&quot;">​</a></h2><p>用手机扫码。登录<strong>同一</strong>账号和 workspace。需要的话走完 MFA / SSO / passkey。主机就会出现在 <strong>Remote</strong> 里。</p><p>每台手机和每台主机都要分别配对。2026-06-08 之后没用过的旧连接，升级两端应用后重新配对。</p><h2 id="第-3-步-—-从手机干活" tabindex="-1">第 3 步 — 从手机干活 <a class="header-anchor" href="#第-3-步-—-从手机干活" aria-label="Permalink to &quot;第 3 步 — 从手机干活&quot;">​</a></h2><p>打开 <strong>Remote</strong>，选已连接电脑，开新任务或续上旧的。</p><p>主机必须<strong>醒着且在线</strong>。关桌面应用、睡眠、掉网，Remote 就停。</p><table tabindex="0"><thead><tr><th>主机细节</th><th>约束</th></tr></thead><tbody><tr><td>Mac 笔记本，开盖，插电</td><td>Remote 可以保持</td></tr><tr><td>Mac 笔记本，合盖</td><td>还要外接显示器</td></tr><tr><td>选择 <strong>Sleep</strong></td><td>Remote 停</td></tr><tr><td>Windows + Computer Use</td><td>会话保持解锁；Computer Use 占前台</td></tr></tbody></table><h2 id="在手机上做什么" tabindex="-1">在手机上做什么 <a class="header-anchor" href="#在手机上做什么" aria-label="Permalink to &quot;在手机上做什么&quot;">​</a></h2><ol><li><strong>看任务</strong>，包括什么时候需要你输入。</li><li><strong>审批</strong>命令和动作，Codex 才在那台主机上继续。</li><li><strong>审</strong>回复、改动文件、diff、测试结果。</li><li><strong>开</strong>针对某台已连接电脑和项目的新任务。</li></ol><p>主机上的沙箱、审批策略和组织设置仍然生效。</p><h2 id="remote-vs-cloud-vs-app-server" tabindex="-1">Remote vs Cloud vs app-server <a class="header-anchor" href="#remote-vs-cloud-vs-app-server" aria-label="Permalink to &quot;Remote vs Cloud vs app-server&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Remote</th><th>Cloud</th><th><code>codex app-server</code></th></tr></thead><tbody><tr><td>活跑在哪</td><td>已配对的 Mac / Windows（或其 SSH 项目）</td><td>OpenAI 托管环境</td><td>你自己拉起的进程，通常给自研客户端</td></tr><tr><td>笔记本要醒着</td><td><strong>要</strong></td><td>不要</td><td>取决于那个进程</td></tr><tr><td>典型入口</td><td>ChatGPT 手机 <strong>Remote</strong></td><td><a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a></td><td><code>codex app-server --listen …</code></td></tr><tr><td>何时用</td><td>手机审批 / 带方向本机会话</td><td>并行托管任务</td><td>把 Codex 嵌进产品</td></tr></tbody></table><p>协议：<a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">Codex App Server</a>。SSH 项目和会话交接：<a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a>。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>结果</th><th>改做</th></tr></thead><tbody><tr><td>两端 workspace 不同</td><td>主机不出现</td><td>同一账号<strong>和</strong> workspace</td></tr><tr><td>让笔记本睡觉</td><td>会话掉线</td><td>保持主机醒着；或改用 <a href="./codex-cloud.html">Cloud</a></td></tr><tr><td>以为有 Cloud 那种隔离</td><td>手机在开<strong>你的</strong>机器</td><td>不要把 Remote 当沙箱</td></tr><tr><td>把 app-server 暴露到公网</td><td>放量期默认可能未认证</td><td>用官方 Remote 配对，或 <code>wss://</code> + 认证；优先 VPN</td></tr><tr><td>在 CLI 里找配对</td><td>没有这条路径</td><td>从桌面应用开始</td></tr></tbody></table><h2 id="实际用例" tabindex="-1">实际用例 <a class="header-anchor" href="#实际用例" aria-label="Permalink to &quot;实际用例&quot;">​</a></h2><p>下班前在桌面 Codex 里开一轮 test-and-fix。火车上打开 <strong>Remote</strong>，批一次 <code>pnpm test</code>，看 diff。笔记本要睡就别用 Remote——合盖前把活送到 <a href="./codex-cloud.html">Cloud</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>配对、SSH、交接、排错 → <a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a></li><li>合盖也要跑的托管任务 → <a href="./codex-cloud.html">Cloud</a></li><li>桌面 Chat / Work / Codex → <a href="./chatgpt-work.html">Work</a> · <a href="./codex-ai.html">产品线</a></li></ol><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/remote" target="_blank" rel="noreferrer">Codex Remote（落地页）</a></li><li><a href="https://learn.chatgpt.com/docs/remote" target="_blank" rel="noreferrer">Remote（文档）</a></li><li><a href="https://learn.chatgpt.com/docs/remote-connections" target="_blank" rel="noreferrer">Remote connections</a></li><li><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a></li><li><a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a></li></ul>`,37)])])}const f=e(d,[["render",n]]);export{b as __pageData,f as default};
